generate.initial_sparql:
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investor ?investorId ?investorName ?sectorFocus WHERE {
  ?investor a wm:Investor .
  OPTIONAL { ?investor wm:investorId ?investorId . }
  OPTIONAL { ?investor wm:investorName ?investorName . }
  ?investor wm:sectorFocus ?sectorFocus .
  FILTER(CONTAINS(LCASE(STR(?sectorFocus)), "real estate"))
  FILTER NOT EXISTS {
    ?investor wm:hasHolding ?holding .
    ?holding wm:hasSector ?sector .
    ?sector rdfs:label ?sectorLabel .
    FILTER(CONTAINS(LCASE(STR(?sectorLabel)), "real estate"))
  }
}

